const now = new Date();
const today = now.toISOString().split('T')[0];
const yesterday = new Date(now.getTime() - 86400000).toISOString().split('T')[0];

return [{
  json: {
    report_date: today,
    period_start: yesterday,
    period_end: today,
    generated_at: now.toISOString()
  }
}];

const openIssues = $('Fetch Open Agent Issues').first().json;
const closedIssues = $('Fetch Closed Agent Issues').first().json;
const openPRs = $('Fetch Open Agent PRs').first().json;
const closedPRs = $('Fetch Closed Agent PRs').first().json;
const reportDate = $('Set Report Date').first().json;

const openCount = openIssues.total_count || 0;
const closedCount = closedIssues.total_count || 0;
const openPRCount = openPRs.total_count || 0;
const closedPRCount = closedPRs.total_count || 0;

const openIssuesList = (openIssues.items || []).slice(0, 10).map(i => ({
  number: i.number,
  title: i.title,
  created: i.created_at,
  labels: i.labels.map(l => l.name)
}));

const closedIssuesList = (closedIssues.items || []).slice(0, 10).map(i => ({
  number: i.number,
  title: i.title,
  closed: i.closed_at,
  labels: i.labels.map(l => l.name)
}));

const openPRList = (openPRs.items || []).slice(0, 10).map(i => ({
  number: i.number,
  title: i.title,
  created: i.created_at
}));

const closedPRList = (closedPRs.items || []).slice(0, 10).map(i => ({
  number: i.number,
  title: i.title,
  closed: i.closed_at
}));

return [{
  json: {
    report_date: reportDate.report_date,
    generated_at: reportDate.generated_at,
    summary: {
      open_issues: openCount,
      completed_today: closedCount,
      pending_issues: openCount,
      open_prs: openPRCount,
      merged_prs: closedPRCount,
      total_activity: openCount + closedCount + openPRCount + closedPRCount
    },
    open_issues: openIssuesList,
    completed_issues: closedIssuesList,
    open_prs: openPRList,
    merged_prs: closedPRList
  }
}];

const data = $input.first().json;
const s = data.summary;

let report = '# 📊 GhostForge Agent — Daily Report\n';
report += '**Date:** ' + data.report_date + '\n';
report += '**Generated:** ' + data.generated_at + '\n\n';

report += '## Summary\n\n';
report += '| Metric | Count |\n';
report += '|--------|-------|\n';
report += '| Open Issues (Agent) | ' + s.open_issues + ' |\n';
report += '| Completed (24h) | ' + s.completed_today + ' |\n';
report += '| Pending Issues | ' + s.pending_issues + ' |\n';
report += '| Open PRs (Agent) | ' + s.open_prs + ' |\n';
report += '| Merged PRs (24h) | ' + s.merged_prs + ' |\n';
report += '| **Total Activity** | **' + s.total_activity + '** |\n\n';

if (data.open_issues.length > 0) {
  report += '## Open Issues\n\n';
  data.open_issues.forEach(i => {
    report += '- #' + i.number + ': ' + i.title + '\n';
  });
  report += '\n';
}

if (data.completed_issues.length > 0) {
  report += '## Completed Issues (24h)\n\n';
  data.completed_issues.forEach(i => {
    report += '- #' + i.number + ': ' + i.title + '\n';
  });
  report += '\n';
}

if (data.open_prs.length > 0) {
  report += '## Open PRs\n\n';
  data.open_prs.forEach(p => {
    report += '- PR #' + p.number + ': ' + p.title + '\n';
  });
  report += '\n';
}

if (data.merged_prs.length > 0) {
  report += '## Merged PRs (24h)\n\n';
  data.merged_prs.forEach(p => {
    report += '- PR #' + p.number + ': ' + p.title + '\n';
  });
  report += '\n';
}

report += '---\n*Generated by GhostForge Agent Monitor*';

return [{ json: { ...data, report_markdown: report } }];

